// Money = integer cents. Parse "140k", "140,000", "$140,000.50".
function moneyNums(t){var m=String(t==null?"":t).match(/\d[\d,]*(\.\d+)?\s*[km]?/gi)||[];return m.slice(0,2).map(function(s){var mul=/k$/i.test(s)?1e3:/m$/i.test(s)?1e6:1;return Math.round(parseFloat(s.replace(/[,\sKkMm]/g,""))*mul*100)}).filter(function(n){return isFinite(n)})}
function toCents(v){var n=moneyNums(v);return n.length?n[0]:null}
function centsPlain(c){return Number.isInteger(c)?String(c/100):""}
function fmtMoney(c,cur,compact){if(!Number.isInteger(c))return "";try{return new Intl.NumberFormat(undefined,compact?{style:"currency",currency:cur||"USD",notation:"compact",maximumFractionDigits:1}:{style:"currency",currency:cur||"USD",minimumFractionDigits:0,maximumFractionDigits:c%100?2:0}).format(c/100)}catch(e){return (c/100).toFixed(2)}}
